# Canvas: domain_adaptation_entities_v3
# Path: app/features/domain_adaptation/domain/entities.py

import uuid
from typing import List
from datetime import datetime, timezone
from pydantic import BaseModel, Field, ConfigDict

class TimeSlice(BaseModel):
    """Represents a calculated window of dense speech to be extracted from RAM."""
    start_sec: float
    end_sec: float

    model_config = ConfigDict(frozen=True)

class ScoutResult(BaseModel):
    """The aggregated raw text preview generated by the Scout model."""
    source_id: uuid.UUID
    combined_text: str = Field(description="The concatenated dirty text from all RAM audio slices.")

    model_config = ConfigDict(frozen=True)

class DomainGlossary(BaseModel):
    """The final, validated domain context dictating hotwords for Whisper Large."""
    id: uuid.UUID = Field(default_factory=uuid.uuid4)
    source_id: uuid.UUID
    industry: str
    sub_domains: List[str]
    hotword_string: str
    initial_prompt_string: str = Field(default="")
    created_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))

    model_config = ConfigDict(from_attributes=True)